    [RelayCommand]
    private async Task CalculateAsync()
    {
        if (!double.TryParse(HeightCm, NumberStyles.Any, CultureInfo.InvariantCulture, out var height) &&
            !double.TryParse(HeightCm, out height))
        {
            HealthAdvice = "請輸入正確的身高數值（公分）！";
