        }

        if (!double.TryParse(WeightKg, NumberStyles.Any, CultureInfo.InvariantCulture, out var weight) &&
            !double.TryParse(WeightKg, out weight))
        {
            HealthAdvice = "請輸入正確的體重數值（公斤）！";
            return;
        }

        if (height <= 0 || weight <= 0)
        {
            HealthAdvice = "身高與體重必須大於 0！";
            return;
        }

        var bmi = _bmiCalculatorService != null
            ? _bmiCalculatorService.CalculateBmi(height, weight)
            : Math.Round(weight / Math.Pow(height / 100.0, 2), 1);

        BmiValue = bmi.ToString("0.0", CultureInfo.InvariantCulture);

        var heightM = height / 100.0;
        var minIdeal = Math.Round(18.5 * heightM * heightM, 1);
        var maxIdeal = Math.Round(24.0 * heightM * heightM, 1);
        IdealWeightRange = $"理想體重範圍：{minIdeal:0.0} kg ~ {maxIdeal:0.0} kg";

        var greeting = !string.IsNullOrWhiteSpace(UserName) ? $"{UserName} 您好！" : string.Empty;

        // 判定衛福部標準級距：過輕 <18.5、正常 18.5~24、過重 24~27、輕度肥胖 27~30、中度肥胖 30~35、重度肥胖 >=35
        if (bmi < 18.5)
        {
            BmiCategory = "體重過輕 (Underweight)";
            HealthAdvice = $"{greeting}您的體重偏輕，建議均衡增加蛋白質與優質熱量攝取，並搭配適度肌力訓練以增加肌肉量。";
        }
        else if (bmi < 24.0)
        {
            BmiCategory = "正常範圍 (Normal)";
            HealthAdvice = $"{greeting}恭喜！您的體位處於健康正常範圍，請保持規律運動與均衡飲食習慣！";
        }
        else if (bmi < 27.0)
        {
            BmiCategory = "過重 (Overweight)";
            HealthAdvice = $"{greeting}體重已達過重標準，建議適度控制精緻糖與熱量攝取，每週進行至少150分鐘中強度有氧運動。";
        }
        else if (bmi < 30.0)
        {
            BmiCategory = "輕度肥胖 (Mild Obesity)";
            HealthAdvice = $"{greeting}已達輕度肥胖標準，建議調整日常飲食結構，多攝取高纖蔬果，並建立規律運動計畫。";
        }
        else if (bmi < 35.0)
        {
            BmiCategory = "中度肥胖 (Moderate Obesity)";
            HealthAdvice = $"{greeting}已達中度肥胖，建議諮詢家醫科醫師或營養師，擬定個人化減重與飲食生活改善目標。";
        }
        else
        {
            BmiCategory = "重度肥胖 (Severe Obesity)";
            HealthAdvice = $"{greeting}已達重度肥胖，心血管與代謝疾病風險顯著升高，強烈建議尋求減重專科或代謝醫療門診協助。";
        }

        await Task.CompletedTask;
    }

